// Local-first lesson service: curriculum comes from the bundled
// src/content/lessons/index.json (generated by scripts/build-lesson-index.mjs),
// bodies load lazily from Markdown files. Completions live in the local store.
import indexData from '../content/lessons/index.json';
import { addXp, getProgress, saveProgress, touchActivity } from './store';

export interface Module {
  id: string;
  code: string;
  title_en: string;
  title_id: string;
  objective_id: string | null;
  objective_en: string | null;
}

export interface Lesson {
  id: string;
  code: string;
  moduleId: string;
  title_en: string;
  title_id: string;
  duration_min: number | null;
}

export interface LessonFull extends Lesson {
  body_md: string | null;
}

export interface LevelRow {
  id: string;
  name: string;
  description: string | null;
}

interface IndexLesson {
  id: string;
  code: string;
  title_en: string;
  title_id: string;
  duration_min: number;
  file: string;
  file_en?: string | null;
}
interface IndexModule {
  id: string;
  code: string;
  title_en: string;
  title_id: string;
  objective_id: string | null;
  objective_en: string | null;
  lessons: IndexLesson[];
}
interface IndexLevel {
  id: string;
  modules: IndexModule[];
}

const LEVELS = (indexData as { levels: IndexLevel[] }).levels;

// Vite: raw markdown chunks, loaded on demand per lesson.
const mdModules = import.meta.glob('../content/lessons/*/*.md', {
  query: '?raw',
  import: 'default',
}) as Record<string, () => Promise<string>>;

function stripFrontmatter(text: string): string {
  return text.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/, '');
}

function findLesson(lessonId: string): { level: IndexLevel; module: IndexModule; lesson: IndexLesson } | null {
  for (const level of LEVELS) {
    for (const module of level.modules) {
      const lesson = module.lessons.find((l) => l.id === lessonId);
      if (lesson) return { level, module, lesson };
    }
  }
  return null;
}

/** Modul pemilik sebuah lesson (untuk header meta). */
export function moduleOfLesson(lessonId: string): Module | null {
  const found = findLesson(lessonId);
  if (!found) return null;
  const m = found.module;
  return {
    id: m.id,
    code: m.code,
    title_en: m.title_en,
    title_id: m.title_id,
    objective_id: m.objective_id ?? null,
    objective_en: m.objective_en ?? null,
  };
}

/** Lesson sebelum & sesudah dalam modul yang sama (navigasi bawah). */
export function prevNextLesson(lessonId: string): { prev: Lesson | null; next: Lesson | null } {
  const found = findLesson(lessonId);
  if (!found) return { prev: null, next: null };
  const toLesson = (l: IndexLesson): Lesson => ({
    id: l.id,
    code: l.code,
    moduleId: found.module.id,
    title_en: l.title_en,
    title_id: l.title_id,
    duration_min: l.duration_min,
  });
  const list = found.module.lessons;
  const i = list.findIndex((l) => l.id === lessonId);
  return {
    prev: i > 0 ? toLesson(list[i - 1]) : null,
    next: i >= 0 && i + 1 < list.length ? toLesson(list[i + 1]) : null,
  };
}

/** Daftar modul untuk satu level, urut kode modul. */
export async function modules(levelId: string): Promise<Module[]> {
  const level = LEVELS.find((l) => l.id === levelId);
  if (!level) return [];
  return level.modules.map((m) => ({
    id: m.id,
    code: m.code,
    title_en: m.title_en,
    title_id: m.title_id,
    objective_id: m.objective_id,
    objective_en: m.objective_en,
  }));
}

/** Daftar pelajaran untuk satu modul. */
export async function lessons(moduleId: string): Promise<Lesson[]> {
  for (const level of LEVELS) {
    const module = level.modules.find((m) => m.id === moduleId);
    if (module) {
      return module.lessons.map((l) => ({
        id: l.id,
        code: l.code,
        moduleId: module.id,
        title_en: l.title_en,
        title_id: l.title_id,
        duration_min: l.duration_min,
      }));
    }
  }
  return [];
}

/** Satu pelajaran lengkap termasuk body_md. Null bila tidak ada. */
export async function lessonDetail(
  lessonId: string,
  lang: 'en' | 'id' = 'id',
): Promise<LessonFull | null> {
  const found = findLesson(lessonId);
  if (!found) return null;
  const { module, lesson } = found;
  const file = lang === 'en' && lesson.file_en ? lesson.file_en : lesson.file;
  const key = `../content/lessons/${file}`;
  const loader = mdModules[key];
  let body: string | null = null;
  if (loader) {
    try {
      body = stripFrontmatter(await loader());
    } catch {
      body = null;
    }
  }
  return {
    id: lesson.id,
    code: lesson.code,
    moduleId: module.id,
    title_en: lesson.title_en,
    title_id: lesson.title_id,
    duration_min: lesson.duration_min,
    body_md: body,
  };
}

/** Daftar level kurikulum. */
export async function levels(): Promise<LevelRow[]> {
  return LEVELS.map((l) => ({ id: l.id, name: l.id, description: null }));
}

/** Tandai pelajaran selesai (+10 XP). */
export async function completeLesson(lessonId: string): Promise<void> {
  const p = getProgress();
  if (!p.completedLessons[lessonId]) {
    p.completedLessons[lessonId] = new Date().toISOString();
    saveProgress();
    addXp(10);
  } else {
    touchActivity();
  }
}

/** Batalkan tanda selesai (sekaligus tarik kembali +10 XP-nya). */
export async function uncompleteLesson(lessonId: string): Promise<void> {
  const p = getProgress();
  if (p.completedLessons[lessonId]) {
    delete p.completedLessons[lessonId];
    p.xp = Math.max(0, p.xp - 10);
    saveProgress();
  }
  touchActivity();
}

/** Set id pelajaran yang sudah diselesaikan. */
export async function completedLessonIds(): Promise<Set<string>> {
  return new Set(Object.keys(getProgress().completedLessons));
}

/** Semua id pelajaran di bawah satu level. */
export async function lessonIdsForLevel(levelId: string): Promise<string[]> {
  const level = LEVELS.find((l) => l.id === levelId);
  if (!level) return [];
  return level.modules.flatMap((m) => m.lessons.map((l) => l.id));
}
